fn total_cost(prices: Vec<Int>, quantities: Vec<Int>) -> Int {
    let mut sum = 0
    for i in 0.len(prices) {
        sum = sum + prices.get(i) * quantities.get(i)
    }
    sum
}

fn find_most_expensive(prices: Vec<Int>, names: Vec<Str>) -> Str {
    let mut max_price = 0
    let mut most_expensive = ""
    for i in 0.len(prices) {
        if prices.get(i) > max_price {
            max_price = prices.get(i)
            most_expensive = names.get(i)
        }
    }
    most_expensive
}

